import { test, expect } from 'bun:test'
import { parseCSV } from './csv'

test('基本解析', () => {
  const csv = 'name,age\nAlice,30\nBob,25'
  const result = parseCSV(csv)
  expect(result).toEqual([
    { name: 'Alice', age: '30' },
    { name: 'Bob', age: '25' },
  ])
})

test('引号内逗号', () => {
  const csv = 'name,desc\nAlice,"Hello, World"'
  const result = parseCSV(csv)
  expect(result[0]).toEqual({ name: 'Alice', desc: 'Hello, World' })
})

test('引号转义双引号', () => {
  const csv = 'name,quote\nBob,"He said ""hi"""'
  const result = parseCSV(csv)
  expect(result[0]).toEqual({ name: 'Bob', quote: 'He said "hi"' })
})

test('跨行字段', () => {
  const csv = 'name,desc\nAlice,"Line1\nLine2"'
  const result = parseCSV(csv)
  expect(result[0]).toEqual({ name: 'Alice', desc: 'Line1\nLine2' })
})

test('空字段', () => {
  const csv = 'a,b,c\n1,,3'
  const result = parseCSV(csv)
  expect(result[0]).toEqual({ a: '1', b: '', c: '3' })
})

test('只有表头', () => {
  const csv = 'a,b,c'
  const result = parseCSV(csv)
  expect(result).toEqual([])
})

test('空字符串', () => {
  expect(parseCSV('')).toEqual([])
})

test('单个字段', () => {
  const csv = 'name\nAlice\nBob'
  const result = parseCSV(csv)
  expect(result).toEqual([{ name: 'Alice' }, { name: 'Bob' }])
})

test('末尾换行', () => {
  const csv = 'a,b\n1,2\n'
  const result = parseCSV(csv)
  expect(result).toEqual([{ a: '1', b: '2' }])
})

test('引号包裹的整个字段含换行和逗号', () => {
  const csv = 'id,text\n1,"foo,\nbar,\nbaz"\n2,plain'
  const result = parseCSV(csv)
  expect(result[0]).toEqual({ id: '1', text: 'foo,\nbar,\nbaz' })
  expect(result[1]).toEqual({ id: '2', text: 'plain' })
})
